{
  "name": "量子中央控制器",
  "name_en": "Quantum Central Controller (QCC)",
  "manufacturer": "QuTech",
  "description": "用于量子比特实验控制的硬件控制器。该设备通过 SCPI 接口与上位机通信，可管理控制参数、处理 QISA 指令与控制存储内容，并支持数字 I/O 协议校准，用于协调量子实验中的时序与触发。",
  "description_en": "A hardware controller for qubit experiment control. It communicates with host software through SCPI, manages control parameters, handles QISA instructions and control-store contents, and supports digital I/O protocol calibration for coordinating timing and triggering in quantum experiments.",
  "actions": [
    {
      "action_name": "auto-add_standard_parameters",
      "description": "自动添加设备的标准控制参数。",
      "description_en": "Automatically add the device's standard control parameters."
    },
    {
      "action_name": "auto-add_additional_parameters",
      "description": "添加设备的附加专用参数，并生成用于上传指令的控制接口。",
      "description_en": "Add additional device-specific parameters and create control interfaces for uploading instructions."
    },
    {
      "action_name": "auto-get_idn",
      "description": "读取设备身份信息。",
      "description_en": "Read the device identification information."
    },
    {
      "action_name": "auto-print_readable_idn",
      "description": "以易读格式输出设备身份信息。",
      "description_en": "Print the device identification information in a human-readable format."
    },
    {
      "action_name": "auto-print_qisa_opcodes",
      "description": "输出设备支持的 QISA 操作码列表。",
      "description_en": "Print the list of QISA opcodes supported by the device."
    },
    {
      "action_name": "auto-print_control_store",
      "description": "输出设备当前的控制存储内容。",
      "description_en": "Print the current control-store contents of the device."
    },
    {
      "action_name": "auto-print_qisa_with_control_store",
      "description": "输出带有控制存储映射信息的 QISA 指令内容。",
      "description_en": "Print QISA instructions together with their control-store mapping information."
    },
    {
      "action_name": "auto-output_dio_calibration_data",
      "description": "输出用于数字 I/O 协议校准的数据。",
      "description_en": "Output data used for digital I/O protocol calibration."
    },
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "校准设备的数字 I/O 协议时序与序列匹配。",
      "description_en": "Calibrate the device's digital I/O protocol timing and sequence matching."
    },
    {
      "action_name": "auto-getOperationComplete",
      "description": "获取操作完成状态。",
      "description_en": "Get operation complete status."
    },
    {
      "action_name": "auto-get_operation_complete",
      "description": "获取操作完成状态。",
      "description_en": "Get operation complete status."
    }
  ],
  "tag_hints": [
    "quantum control",
    "QCC",
    "SCPI instrument",
    "QISA instruction control",
    "DIO calibration",
    "qubit experiment timing",
    "trigger coordination",
    "FPGA-based controller"
  ]
}

